/**
 * Layout component that queries for data
 * with Gatsby's useStaticQuery component
 *
 * See: https://www.gatsbyjs.com/docs/how-to/querying-data/use-static-query/
 */

import * as React from "react"
import { useStaticQuery, graphql, Link } from "gatsby"

import Header from "./header"
import "./layout.css"

// handle dark vs. light theme switches
function getTheme() {
  return document.documentElement.dataset.theme;
}

function setTheme(theme) {
  document.documentElement.dataset.theme = theme;
  localStorage.setItem("theme", theme);
}

function handleToggle() {
  const current = getTheme();
  setTheme(current === "dark" ? "light" : "dark");
}

const Layout = ({ children }) => {
  const data = useStaticQuery(graphql`
    query SiteTitleQuery {
      site {
        siteMetadata {
          title
        }
      }
      currentBuildDate {
        currentDate
      }
    }
  `)

  const headerLinks = [
    {
      text: "Blog",
      url: "/blog",
    },
    {
      text: "Research",
      url: "/research",
    },
    {
      text: "Teaching",
      url: "/teaching",
    },

  ]

  return (
    <>
      <hr class="header-line" />
      <Header siteTitle={data.site.siteMetadata?.title || `Title`} />
      <hr class="header-line" />


      <ul className="header-nav">
        {headerLinks.map(link => (
          <li key={link.url}>
            <Link title={link.text} className="header-bold" to={link.url}>{link.text}</Link>
          </li>
        ))}
      </ul>


      <div
        style={{
          margin: `0 auto`,
          maxWidth: `var(--size-content)`,
          padding: `var(--size-gutter)`,
        }}
      >
        <main>{children}</main>
        <footer
          style={{
            marginTop: `var(--space-5)`,
            fontSize: `var(--font-sm)`,
          }}
        >
          © {new Date().getFullYear()} Alysa Meng &middot; Last updated {data.currentBuildDate.currentDate} &middot; 𖡡 Seattle, WA, USA.
          <p>Check out a print version (coming soon!) and <button onClick={handleToggle}>toggle</button> the color theme.</p>
        </footer>

      </div>
      <hr class="header-line" />
    </>
  )
}

export default Layout
